WITH e AS (SELECT * FROM mob_events WHERE zone_id = {zone:Int64} AND mob_name = {name:String} AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')), rl AS (SELECT max(release) AS release FROM captures WHERE capture_id IN (SELECT capture_id FROM e)) SELECT e.kind AS kind, e.skill_id AS skill, e.spell_id AS spell, any(s.name) AS spell_name, uniqExact(e.player_id, intDiv(e.ts_ms, 1000)) AS n FROM e LEFT JOIN (SELECT id, name FROM spell_names WHERE release = (SELECT release FROM rl)) s ON s.id = e.spell_id GROUP BY e.kind, e.skill_id, e.spell_id ORDER BY e.kind, n DESC
